def _is_table_header(line: str) -> bool:
    stripped = line.strip()
    if not stripped or stripped.startswith('#'):
        return False
    return stripped.startswith('[') and stripped.endswith(']')


TIMEOUT_KEY_RE = re.compile(r'^(tool_timeout_sec|startup_timeout_sec)\s*=')


def _timeout_key(line: str) -> Optional[str]:
    stripped = line.lstrip()
    if stripped.startswith('#'):
        return None
    match = TIMEOUT_KEY_RE.match(stripped)
    return match.group(1) if match else None


def render_server_timeouts(text: str, tool_timeout: int, startup_timeout: int) -> Optional[str]:
    '''Return text with the two MCP timeouts set, or None when unsafe.

    Only the exact, unique table header written by the Codex CLI
    ([mcp_servers.claude-advisor], quoted or not) is accepted; every other
    byte of the file, including all other tables and comments, is preserved.
    A missing or ambiguous header returns None so the caller reports pending
    instead of guessing at a string that merely looks like a table.
    '''
    lines = text.splitlines(keepends=True)
    headers = [index for index, line in enumerate(lines) if line.strip() in MCP_TABLE_HEADERS]
    if len(headers) != 1:
        return None
    header = headers[0]
    end = len(lines)
    for index in range(header + 1, len(lines)):
        if _is_table_header(lines[index]):
            end = index
            break
    head = lines[header]
    if not head.endswith('\n'):
        head = head + '\n'
    wanted = [('tool_timeout_sec', tool_timeout), ('startup_timeout_sec', startup_timeout)]
    body = [key + ' = ' + str(value) + '\n' for key, value in wanted]
    for line in lines[header + 1:end]:
        if _timeout_key(line) is not None:
            continue
        body.append(line)
    return ''.join([head] + body + lines[end:])


def write_server_timeouts(config_path: Path) -> None:
    '''Atomically persist the MCP timeouts, preserving every other setting.'''
    try:
        info = config_path.lstat()
    except FileNotFoundError:
        raise InstallerError('mcp_config_error', '未找到 Codex 配置文件；超时配置待人工完成。')
    except OSError:
        raise InstallerError('mcp_config_error', '无法检查 Codex 配置文件。')
    if stat.S_ISLNK(info.st_mode):
        raise InstallerError('mcp_config_error', 'Codex 配置文件是符号链接，已拒绝写入。')
    if not stat.S_ISREG(info.st_mode):
        raise InstallerError('mcp_config_error', 'Codex 配置文件不是普通文件，已拒绝写入。')
    uid = current_uid()
    if uid is not None and info.st_uid != uid:
        raise InstallerError('mcp_config_error', 'Codex 配置文件不属于当前用户，已拒绝写入。')
    try:
        text = config_path.read_text(encoding='utf-8')
    except (OSError, UnicodeDecodeError):
        raise InstallerError('mcp_config_error', '无法读取 Codex 配置文件。')
    rendered = render_server_timeouts(text, MCP_TOOL_TIMEOUT_SEC, MCP_STARTUP_TIMEOUT_SEC)
    if rendered is None:
        raise InstallerError('mcp_config_error', '未能唯一定位 claude-advisor 配置表，未做任何猜测写入。')
    if rendered == text:
        return
    mode = stat.S_IMODE(info.st_mode) or 0o600
    atomic_write_bytes(config_path, rendered.encode('utf-8'), mode)


def parse_mcp_get(result: Optional[subprocess.CompletedProcess]) -> Optional[Dict[str, Any]]:
    '''Parse codex mcp get <NAME> --json output; the output is never echoed.'''
    if result is None or result.returncode != 0:
        return None
    stdout = result.stdout if isinstance(result.stdout, str) else ''
    try:
        data = json.loads(stdout)
    except ValueError:
        return None
    return data if isinstance(data, dict) else None


def mcp_entry_matches_bridge(entry: Dict[str, Any]) -> bool:
    transport = entry.get('transport')
    if not isinstance(transport, dict):
        return False
    expected = expected_transport()
    if transport.get('command') != expected['command']:
        return False
    args = transport.get('args')
    if not isinstance(args, list):
        return False
    return [str(item) for item in args] == expected['args']


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def mcp_entry_timeouts_ok(entry: Dict[str, Any]) -> bool:
    tool = entry.get('tool_timeout_sec')
    startup = entry.get('startup_timeout_sec')
    return (
        _is_number(tool) and tool >= MCP_TOOL_TIMEOUT_SEC
        and _is_number(startup) and startup >= MCP_STARTUP_TIMEOUT_SEC
    )


def mcp_entry_enabled(entry: Dict[str, Any]) -> bool:
    return entry.get('enabled') is not False


def mcp_not_found(result: Optional[subprocess.CompletedProcess]) -> bool:
    '''True only for the known no-such-server error reported on stderr.'''
    if result is None or result.returncode == 0:
        return False
    stderr = result.stderr if isinstance(result.stderr, str) else ''
    return MCP_NOT_FOUND_MARKER in stderr.lower()


def get_mcp_entry() -> Optional[Dict[str, Any]]:
    return parse_mcp_get(run_codex(['codex', 'mcp', 'get', MCP_SERVER_NAME, '--json']))


def write_timeouts_and_recheck() -> Tuple[bool, List[str]]:
    '''Persist the timeouts, then re-check with the CLI before claiming done.'''
    try:
        write_server_timeouts(codex_config_path())
    except InstallerError:
        return False, [MCP_TIMEOUT_PENDING]
    entry = get_mcp_entry()
    if (
        entry is None
        or not mcp_entry_matches_bridge(entry)
        or not mcp_entry_enabled(entry)
        or not mcp_entry_timeouts_ok(entry)
    ):
        return False, [MCP_TIMEOUT_PENDING]
    return True, [MCP_REGISTERED_OK]


def register_mcp_server() -> Tuple[bool, List[str]]:
    '''Register the key-free MCP entry and persist its timeouts.

    An entry is only reported as registered when the Codex CLI confirms both
    the transport (command/args) and the persistent timeouts; anything that
    cannot be confirmed is reported as pending instead of being claimed.
    '''
    get_result = run_codex(['codex', 'mcp', 'get', MCP_SERVER_NAME, '--json'])
    entry = parse_mcp_get(get_result)

    if entry is not None:
        if not mcp_entry_matches_bridge(entry):
            return False, [MCP_EXISTING_UNKNOWN]
        if not mcp_entry_enabled(entry):
            return False, [MCP_DISABLED_PENDING]
        if mcp_entry_timeouts_ok(entry):
            return True, [MCP_REUSED_OK]
        return write_timeouts_and_recheck()

    if not mcp_not_found(get_result):
        return False, [MCP_GET_FAILED]

    add_result = run_codex([
        'codex', 'mcp', 'add', MCP_SERVER_NAME, '--',
        PYTHON_BIN, str(BRIDGE_PATH), '--serve', '--config', str(CONFIG_PATH),
    ])
    if add_result is None:
        return False, [MCP_NO_CLI]
    if add_result.returncode != 0:
        return False, [MCP_ADD_FAILED]
    return write_timeouts_and_recheck()

